String _lloc(BuildContext c) => Provider.of<I18n>(c, listen: false).locale;

/// Leeftijd-UI-string in de huidige taal (val terug op EN, dan key).
String lft(BuildContext c, String key, [Map<String, String>? vars]) {
  final m = kLftUi[key];
  var s = m?[_lloc(c)] ?? m?['en'] ?? key;
  vars?.forEach((k, v) => s = s.replaceAll('{$k}', v));
  return s;
}
